  7306              upx_uint64_t vaddr  = get_te64(&phdr->p_vaddr);
  7307              upx_uint64_t filesz = get_te64(&phdr->p_filesz);
  7308              if (!load_va) {
  7309                  load_va = vaddr;
  7310              }
  7311              if ((e_entry - vaddr) < filesz) {
  7312                  off_entry = (e_entry - vaddr) + offset;
  7313                  break;
  7314              }
  7315          }
  7316      }
