  7337      &&  0==get_te64(&phdri[1].p_offset)
  7338      &&  0==get_te64(&phdri[0].p_offset)
  7339      &&     get_te64(&phdri[1].p_filesz) == get_te64(&phdri[1].p_memsz)) {
